class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        seen = {}  # value -> index, for everything to the left of i
        for i, x in enumerate(nums):
            need = target - x
            if need in seen:
                return [seen[need], i]
            seen[x] = i
        return []

class Solution:
    def countDistinct(self, nums: List[int]) -> int:
        seen = set()
        for i in range(len(nums)):

            if nums[i] in seen:
                return  i

            seen.add(nums[i])
        return len(nums)

